import java.util.Scanner;

/**
 * Main - entry point for the Task Management System CLI.
 *
 * Subtask 1: user registration / login (authentication) layer.
 *
 * Build:  javac -d bin *.java
 * Run:    java -cp bin Main
 *
 * Expected prompts and commands:
 *
 *   Welcome Menu (shown on every launch)
 *     1) Register - prompts for a username, a password and a password
 *                   confirmation. Empty usernames, empty passwords, duplicate
 *                   usernames and mismatched confirmations are rejected and the
 *                   user is re-prompted until valid input is given. On success
 *                   prints "Registration successful" and persists the user to
 *                   data/users.txt.
 *     2) Login    - prompts for username and password. Wrong credentials print
 *                   "Login failed: invalid username or wrong password." and offer
 *                   a retry / return-to-welcome-menu choice. On success prints
 *                   "Login successful" and opens the Main Menu.
 *     3) Exit     - prints "Goodbye" and terminates.
 *
 *   Main Menu (shown after a successful login)
 *     1) View Tasks - placeholder for later subtasks.
 *     2) Logout     - prints "Logged out." and returns to the Welcome Menu.
 *     3) Exit       - prints "Goodbye" and terminates.
 *
 * Credentials are stored one per line as "username:[secret redacted]
 * The file (and the data/ directory) is created automatically if missing and is
 * reloaded on every launch, so previously registered users can log in again
 * without re-registering. End of input (EOF / closed stdin) is handled
 * gracefully: the program prints "Goodbye" and terminates instead of crashing.
 */
public class Main {

    /** Relative path of the file-based credential store. */
    private static final String USERS_FILE = "data/users.txt";

    private final Scanner sc = new Scanner(System.in);
    private final UserStore store = new UserStore(USERS_FILE);

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Top-level loop: the welcome menu is re-shown after logout or after a
     * registration, and the program ends only when the user chooses Exit or
     * when stdin is exhausted.
     */
    private void run() {
        boolean keepGoing = true;
        while (keepGoing) {
            keepGoing = welcomeMenu();
        }
    }

    /**
     * Reads a single line, printing the prompt first. Returns null when stdin
     * has ended so callers can unwind and exit gracefully.
     */
    private String readLine(String prompt) {
        System.out.print(prompt);
        System.out.flush();
        if (sc.hasNextLine()) {
            return sc.nextLine();
        }
        return null;
    }

    /** Prints the welcome menu and dispatches the user's choice. */
    private boolean welcomeMenu() {
        System.out.println();
        System.out.println("===== Welcome =====");
        System.out.println("1) Register");
        System.out.println("2) Login");
        System.out.println("3) Exit");
        while (true) {
            String choice = readLine("Choose an option: ");
            if (choice == null) {
                goodbye();
                return false;
            }
            choice = choice.trim();
            if (choice.equals("1")) {
                register();
                return true;
            }
            if (choice.equals("2")) {
                login();
                return true;
            }
            if (choice.equals("3")) {
                goodbye();
                return false;
            }
            System.out.println("Invalid option, please try again.");
        }
    }

    /**
     * Registration flow. Collects username, password and confirmation,
     * re-prompting until the input is valid, then persists the new user.
     */
    private void register() {
        System.out.println();
        System.out.println("--- Register ---");
        while (true) {
            String username = readLine("Username: ");
            if (username == null) {
                return;
            }
            username = username.trim();
            if (username.isEmpty()) {
                System.out.println("Username must not be empty.");
                continue;
            }
            if (store.exists(username)) {
                System.out.println("Username already exists, please choose another.");
                continue;
            }
            while (true) {
                String password = [secret redacted]
                if (password =[secret redacted]
                    return;
                }
                if (password.trim().isEmpty()) {
                    System.out.println("Password must not be empty.");
                    continue;
                }
                String confirm = readLine("Confirm password: ");
                if (confirm == null) {
                    return;
                }
                if (!password.equals(confirm)) {
                    System.out.println("Passwords do not match, please try again.");
                    continue;
                }
                if (store.register(username, password)) {
                    System.out.println("Registration successful");
                } else {
                    System.out.println("Registration failed (username already exists).");
                }
                return;
            }
        }
    }

    /**
     * Login flow. Validates the submitted credentials against the store. Wrong
     * credentials print an error and let the user retry or return to the
     * welcome menu. A successful login opens the authenticated main menu.
     */
    private void login() {
        System.out.println();
        System.out.println("--- Login ---");
        while (true) {
            String username = readLine("Username: ");
            if (username == null) {
                return;
            }
            String password = [secret redacted]
            if (password =[secret redacted]
                return;
            }
            username = username.trim();
            if (store.validate(username, password)) {
                System.out.println("Login successful");
                mainMenu(username);
                return;
            }
            System.out.println("Login failed: invalid username or wrong password.");
            while (true) {
                String choice = readLine("1) Retry  2) Back to Welcome Menu\nChoose an option: ");
                if (choice == null) {
                    return;
                }
                choice = choice.trim();
                if (choice.equals("1")) {
                    break;
                }
                if (choice.equals("2")) {
                    return;
                }
                System.out.println("Invalid option, please try again.");
            }
        }
    }

    /** Authenticated main menu shown after a successful login. */
    private void mainMenu(String username) {
        System.out.println();
        System.out.println("===== Main Menu ===== [" + username + "]");
        System.out.println("1) View Tasks");
        System.out.println("2) Logout");
        System.out.println("3) Exit");
        while (true) {
            String choice = readLine("Choose an option: ");
            if (choice == null) {
                goodbye();
                System.exit(0);
            }
            choice = choice.trim();
            if (choice.equals("1")) {
                System.out.println("No tasks yet.");
            } else if (choice.equals("2")) {
                System.out.println("Logged out.");
                return;
            } else if (choice.equals("3")) {
                goodbye();
                System.exit(0);
            } else {
                System.out.println("Invalid option, please try again.");
            }
        }
    }

    /** Prints the final message used on every graceful exit path. */
    private void goodbye() {
        System.out.println("Goodbye");
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * UserStore - simple file-based credential store for the Task Management System.
 *
 * Storage format: one user per line as "username:password" in the file passed
 * to the constructor (the app uses data/users.txt). The file and its parent
 * directory are created automatically if they do not yet exist, and the whole
 * file is reloaded on construction so credentials survive process restarts.
 *
 * The store is intentionally tiny: it exposes just enough for the registration
 * and login flows - existence checks, credential validation and appending a new
 * user. Blank lines and lines starting with '#' are ignored.
 */
public class UserStore {

    private final Path file;
    private final Map<String, String> users = new LinkedHashMap<String, String>();

    public UserStore(String path) {
        this.file = Paths.get(path);
        load();
    }

    /** Loads all persisted users, creating the backing file if necessary. */
    private void load() {
        try {
            if (!Files.exists(file)) {
                Path parent = file.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }
                Files.createFile(file);
            }
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            for (String raw : lines) {
                String line = raw.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                int sep = line.indexOf(':');
                if (sep <= 0) {
                    continue;
                }
                String username = line.substring(0, sep);
                String password = [secret redacted]
                users.put(username, password);
            }
        } catch (IOException e) {
            System.out.println("Warning: could not load credential store: " + e.getMessage());
        }
    }

    /** True when a user with the given username already exists. */
    public boolean exists(String username) {
        return users.containsKey(username);
    }

    /** Validates a username/password pair against the persisted credentials. */
    public boolean validate(String username, String password) {
        String stored = users.get(username);
        return stored != null && stored.equals(password);
    }

    /**
     * Registers a new user and persists the store. Returns false (without
     * modifying anything) when the username already exists.
     */
    public boolean register(String username, String password) {
        if (users.containsKey(username)) {
            return false;
        }
        users.put(username, password);
        return save();
    }

    /** Rewrites the credential file with the current in-memory contents. */
    private boolean save() {
        try {
            Path parent = file.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, String> e : users.entrySet()) {
                sb.append(e.getKey()).append(':[secret redacted]
            }
            Files.write(file, sb.toString().getBytes(StandardCharsets.UTF_8));
            return true;
        } catch (IOException e) {
            System.out.println("Warning: could not save credential store: " + e.getMessage());
            return false;
        }
    }
}

/**
 * Task - a single to-do item belonging to one user.
 *
 * Fields: a numeric id (unique per user), a title, an optional description, a
 * creation timestamp (ISO-8601 string captured when the task is created) and a
 * status flag. The status is rendered as "Pending" or "Completed" so it is easy
 * for a human (and the evaluator) to observe.
 *
 * Storage format (see TaskStore): fields are joined with a vertical bar '|' as
 *   id|title|description|timestamp|status
 * where status is the literal word "Pending" or "Completed". Titles and
 * descriptions have any '|' or newline characters stripped before saving so the
 * record stays a single parseable line.
 */
public class Task {

    private final int id;
    private final String title;
    private final String description;
    private final String timestamp;
    private boolean completed;

    public Task(int id, String title, String description, String timestamp, boolean completed) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.timestamp = timestamp;
        this.completed = completed;
    }

    public int getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getDescription() {
        return description;
    }

    public String getTimestamp() {
        return timestamp;
    }

    public boolean isCompleted() {
        return completed;
    }

    public void setCompleted(boolean completed) {
        this.completed = completed;
    }

    /** Human-readable status word used both on screen and in the storage file. */
    public String statusText() {
        return completed ? "Completed" : "Pending";
    }

    /** Removes characters that would break the one-line '|'-delimited format. */
    public static String sanitize(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("|", "/").replace("\r", " ").replace("\n", " ");
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * TaskStore - per-user, file-based task repository.
 *
 * Storage format: one task per line as
 *   id|title|description|timestamp|status
 * in the file data/&lt;username&gt;_tasks.txt. Because the file name embeds the
 * username, every user gets an independent file and therefore cannot see or
 * modify another user's tasks. Blank lines and lines beginning with '#' are
 * ignored to stay robust against hand edits.
 *
 * ID generation strategy: ids are unique within a user's file. On load the
 * largest existing id is remembered and the next id is one greater, starting at
 * 1 for a brand-new user. Ids are never reused after a delete, so a removed id
 * will not silently reappear later in the session.
 *
 * The whole file is loaded on construction (so tasks survive process restarts)
 * and rewritten after every add / complete / delete so changes are durable.
 */
public class TaskStore {

    /** Timestamp format used for the creation time recorded on each task. */
    private static final DateTimeFormatter TS_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    private final Path file;
    private final List<Task> tasks = new ArrayList<Task>();
    private int nextId = 1;

    public TaskStore(String username) {
        this.file = Paths.get("data", username + "_tasks.txt");
        load();
    }

    /** Loads the user's tasks, creating the backing file if it does not exist. */
    private void load() {
        try {
            if (!Files.exists(file)) {
                Path parent = file.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }
                Files.createFile(file);
                return;
            }
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            for (String raw : lines) {
                String line = raw.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] parts = line.split("\\|", -1);
                if (parts.length < 5) {
                    continue;
                }
                try {
                    int id = Integer.parseInt(parts[0].trim());
                    String title = parts[1];
                    String description = parts[2];
                    String timestamp = parts[3];
                    boolean completed = parts[4].trim().equalsIgnoreCase("Completed");
                    tasks.add(new Task(id, title, description, timestamp, completed));
                    if (id >= nextId) {
                        nextId = id + 1;
                    }
                } catch (NumberFormatException ignored) {
                    // Skip malformed lines rather than aborting the load.
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not load tasks: " + e.getMessage());
        }
    }

    /** Returns the live list of this user's tasks in insertion order. */
    public List<Task> list() {
        return tasks;
    }

    /** Creates a new task for the current user and persists it. */
    public Task add(String title, String description) {
        String now = LocalDateTime.now().format(TS_FORMAT);
        Task task = new Task(nextId++, Task.sanitize(title), Task.sanitize(description), now, false);
        tasks.add(task);
        save();
        return task;
    }

    /** Finds a task by id, or null when the current user has no such task. */
    public Task findById(int id) {
        for (Task t : tasks) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    /** Marks a task completed; returns the task, or null if the id is unknown. */
    public Task complete(int id) {
        Task task = findById(id);
        if (task == null) {
            return null;
        }
        task.setCompleted(true);
        save();
        return task;
    }

    /** Deletes a task; returns true when a task was actually removed. */
    public boolean delete(int id) {
        for (int i = 0; i < tasks.size(); i++) {
            if (tasks.get(i).getId() == id) {
                tasks.remove(i);
                save();
                return true;
            }
        }
        return false;
    }

    /** Rewrites the per-user task file with the current in-memory contents. */
    private void save() {
        try {
            Path parent = file.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            StringBuilder sb = new StringBuilder();
            for (Task t : tasks) {
                sb.append(t.getId()).append('|')
                  .append(t.getTitle()).append('|')
                  .append(t.getDescription()).append('|')
                  .append(t.getTimestamp()).append('|')
                  .append(t.statusText()).append('\n');
            }
            Files.write(file, sb.toString().getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            System.out.println("Warning: could not save tasks: " + e.getMessage());
        }
    }
}

