/** Authenticated main menu shown after a successful login. */
private void mainMenu(String username) {
    TaskStore tasks = new TaskStore(username);
    while (true) {
        System.out.println();
        System.out.println("===== Main Menu ===== [" + username + "]");
        System.out.println("1) Add Task");
        System.out.println("2) List Tasks");
        System.out.println("3) Mark Task Completed");
        System.out.println("4) Delete Task");
        System.out.println("5) Logout");
        System.out.println("6) Exit");
        String choice = readLine("Choose an option: ");
        if (choice == null) {
            goodbye();
            System.exit(0);
        }
        choice = choice.trim();
        if (choice.equals("1")) {
            addTask(tasks);
        } else if (choice.equals("2")) {
            listTasks(tasks);
        } else if (choice.equals("3")) {
            completeTask(tasks);
        } else if (choice.equals("4")) {
            deleteTask(tasks);
        } else if (choice.equals("5")) {
            System.out.println("Logged out.");
            return;
        } else if (choice.equals("6")) {
            goodbye();
            System.exit(0);
        } else {
            System.out.println("Invalid option, please try again.");
        }
    }
}

/** Prompts for a title and description and persists a new task. */
private void addTask(TaskStore tasks) {
    System.out.println();
    System.out.println("--- Add Task ---");
    String title = readLine("Title: ");
    if (title == null) {
        return;
    }
    String description = readLine("Description: ");
    if (description == null) {
        return;
    }
    if (title.trim().isEmpty()) {
        System.out.println("Title must not be empty.");
        return;
    }
    Task task = tasks.add(title.trim(), description.trim());
    System.out.println("Task " + task.getId() + " added: " + task.getTitle());
}

/** Prints every task of the logged-in user with id, metadata and status. */
private void listTasks(TaskStore tasks) {
    System.out.println();
    System.out.println("--- Task List ---");
    List<Task> all = tasks.list();
    if (all.isEmpty()) {
        System.out.println("No tasks yet.");
        return;
    }
    for (Task t : all) {
        System.out.println("ID: " + t.getId()
                + " | Title: " + t.getTitle()
                + " | Description: " + t.getDescription()
                + " | Created: " + t.getTimestamp()
                + " | Status: " + t.statusText());
    }
}

/** Prompts for an id and marks that task Completed. */
private void completeTask(TaskStore tasks) {
    System.out.println();
    System.out.println("--- Mark Task Completed ---");
    Integer id = readId("Task ID to complete: ");
    if (id == null) {
        return;
    }
    if (tasks.complete(id) != null) {
        System.out.println("Task " + id + " marked Completed");
    } else {
        System.out.println("Task " + id + " not found.");
    }
}

/** Prompts for an id and deletes that task from the user's list. */
private void deleteTask(TaskStore tasks) {
    System.out.println();
    System.out.println("--- Delete Task ---");
    Integer id = readId("Task ID to delete: ");
    if (id == null) {
        return;
    }
    if (tasks.delete(id)) {
        System.out.println("Task " + id + " deleted");
    } else {
        System.out.println("Task " + id + " not found.");
    }
}

/**
 * Reads a numeric task id from stdin. Returns null on EOF or invalid
 * (non-numeric) input, printing a short message in the invalid case.
 */
private Integer readId(String prompt) {
    String raw = readLine(prompt);
    if (raw == null) {
        return null;
    }
    try {
        return Integer.valueOf(raw.trim());
    } catch (NumberFormatException e) {
        System.out.println("Please enter a valid numeric task ID.");
        return null;
    }
}

