import java.util.ArrayList;
import java.util.List;

/**
 * Task - a single to-do item belonging to one user.
 *
 * Fields: a numeric id (unique per user), a title, an optional description, a
 * creation timestamp (ISO-8601 string captured when the task is created), a
 * status flag, and - since Subtask 3 - a priority (High/Medium/Low), an
 * optional deadline (ISO date "yyyy-MM-dd") and a list of tags. The status is
 * rendered as "Pending" or "Completed" so it is easy for a human (and the
 * evaluator) to observe.
 *
 * Storage format (see TaskStore): fields are joined with a vertical bar '|' as
 *   id|title|description|timestamp|status|priority|deadline|tags
 * where status is the literal word "Pending" or "Completed", priority is
 * "High"/"Medium"/"Low", deadline is a "yyyy-MM-dd" date (possibly empty) and
 * tags is a comma-separated list (possibly empty). Records written by Subtask 2
 * only have the first five fields; those legacy lines still load and get the
 * defaults priority="Medium", deadline="" and no tags, so existing task data is
 * never lost. Titles, descriptions, tags and the deadline have any '|' or
 * newline characters stripped before saving so the record stays a single
 * parseable line.
 */
public class Task {

    /** Default priority applied to legacy tasks that have no stored priority. */
    public static final String DEFAULT_PRIORITY = "Medium";

    private final int id;
    private final String title;
    private final String description;
    private final String timestamp;
    private boolean completed;
    private String priority;
    private String deadline;
    private final List<String> tags;

    public Task(int id, String title, String description, String timestamp, boolean completed,
                String priority, String deadline, List<String> tags) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.timestamp = timestamp;
        this.completed = completed;
        this.priority = normalizePriority(priority);
        this.deadline = deadline == null ? "" : deadline;
        this.tags = tags == null ? new ArrayList<String>() : tags;
    }

    public int getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getDescription() {
        return description;
    }

    public String getTimestamp() {
        return timestamp;
    }

    public boolean isCompleted() {
        return completed;
    }

    public void setCompleted(boolean completed) {
        this.completed = completed;
    }

    public String getPriority() {
        return priority;
    }

    public void setPriority(String priority) {
        this.priority = normalizePriority(priority);
    }

    public String getDeadline() {
        return deadline;
    }

    public void setDeadline(String deadline) {
        this.deadline = deadline == null ? "" : deadline;
    }

    public List<String> getTags() {
        return tags;
    }

    /** Returns this task's tags joined by commas, e.g. "work,urgent". */
    public String tagsText() {
        return String.join(",", tags);
    }

    /** Human-readable status word used both on screen and in the storage file. */
    public String statusText() {
        return completed ? "Completed" : "Pending";
    }

    /** True when the task carries the given tag (case-insensitive, trimmed). */
    public boolean hasTag(String tag) {
        if (tag == null) {
            return false;
        }
        String needle = tag.trim();
        for (String t : tags) {
            if (t.equalsIgnoreCase(needle)) {
                return true;
            }
        }
        return false;
    }

    /** Maps free-form priority input to one of High/Medium/Low. */
    public static String normalizePriority(String value) {
        if (value == null) {
            return DEFAULT_PRIORITY;
        }
        String v = value.trim().toLowerCase();
        if (v.equals("high")) {
            return "High";
        }
        if (v.equals("low")) {
            return "Low";
        }
        if (v.equals("medium") || v.equals("med")) {
            return "Medium";
        }
        return DEFAULT_PRIORITY;
    }

    /** Parses a comma-separated tag string into a sanitized, de-duplicated list. */
    public static List<String> parseTags(String raw) {
        List<String> result = new ArrayList<String>();
        if (raw == null) {
            return result;
        }
        for (String piece : raw.split(",")) {
            String tag = sanitizeTag(piece);
            if (!tag.isEmpty() && !containsIgnoreCase(result, tag)) {
                result.add(tag);
            }
        }
        return result;
    }

    private static boolean containsIgnoreCase(List<String> list, String value) {
        for (String s : list) {
            if (s.equalsIgnoreCase(value)) {
                return true;
            }
        }
        return false;
    }

    /** Removes characters that would break the one-line '|'-delimited format. */
    public static String sanitize(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("|", "/").replace("\r", " ").replace("\n", " ");
    }

    /** Sanitizes a single tag, also stripping the ',' tag separator. */
    public static String sanitizeTag(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("|", "/").replace(",", " ")
                    .replace("\r", " ").replace("\n", " ").trim();
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * TaskStore - per-user, file-based task repository.
 *
 * Storage format: one task per line as
 *   id|title|description|timestamp|status|priority|deadline|tags
 * in the file data/<username>_tasks.txt. Because the file name embeds the
 * username, every user gets an independent file and therefore cannot see or
 * modify another user's tasks. Blank lines and lines beginning with '#' are
 * ignored to stay robust against hand edits.
 *
 * Backward compatibility: records written before Subtask 3 only contain the
 * first five fields ("id|title|description|timestamp|status"). They still load
 * correctly and receive the defaults priority="Medium", deadline="" and an
 * empty tag list, so no previously persisted data is lost and the program never
 * crashes on old files.
 *
 * ID generation strategy: ids are unique within a user's file. On load the
 * largest existing id is remembered and the next id is one greater, starting at
 * 1 for a brand-new user. Ids are never reused after a delete, so a removed id
 * will not silently reappear later in the session.
 *
 * The whole file is loaded on construction (so tasks survive process restarts)
 * and rewritten after every add / complete / delete so changes are durable.
 */
public class TaskStore {

    /** Timestamp format used for the creation time recorded on each task. */
    private static final DateTimeFormatter TS_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    private final Path file;
    private final List<Task> tasks = new ArrayList<Task>();
    private int nextId = 1;

    public TaskStore(String username) {
        this.file = Paths.get("data", username + "_tasks.txt");
        load();
    }

    /** Loads the user's tasks, creating the backing file if it does not exist. */
    private void load() {
        try {
            if (!Files.exists(file)) {
                Path parent = file.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }
                Files.createFile(file);
                return;
            }
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            for (String raw : lines) {
                String line = raw.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] parts = line.split("\\|", -1);
                if (parts.length < 5) {
                    continue;
                }
                try {
                    int id = Integer.parseInt(parts[0].trim());
                    String title = parts[1];
                    String description = parts[2];
                    String timestamp = parts[3];
                    boolean completed = parts[4].trim().equalsIgnoreCase("Completed");
                    // Subtask 3 attributes are optional; default them when the
                    // line comes from an older version of the program.
                    String priority = parts.length > 5 ? parts[5] : Task.DEFAULT_PRIORITY;
                    String deadline = parts.length > 6 ? parts[6] : "";
                    List<String> tags = parts.length > 7 ? Task.parseTags(parts[7]) : new ArrayList<String>();
                    tasks.add(new Task(id, title, description, timestamp, completed, priority, deadline, tags));
                    if (id >= nextId) {
                        nextId = id + 1;
                    }
                } catch (NumberFormatException ignored) {
                    // Skip malformed lines rather than aborting the load.
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not load tasks: " + e.getMessage());
        }
    }

    /** Returns the live list of this user's tasks in insertion order. */
    public List<Task> list() {
        return tasks;
    }

    /** Creates a new task for the current user and persists it. */
    public Task add(String title, String description, String priority, String deadline, List<String> tags) {
        String now = LocalDateTime.now().format(TS_FORMAT);
        Task task = new Task(nextId++, Task.sanitize(title), Task.sanitize(description), now, false,
                priority, Task.sanitize(deadline), tags);
        tasks.add(task);
        save();
        return task;
    }

    /**
     * Returns the tasks whose priority equals the given value
     * (case-insensitive, e.g. "high"). The result is a new list; the store is
     * not modified.
     */
    public List<Task> filterByPriority(String priority) {
        List<Task> out = new ArrayList<Task>();
        String wanted = Task.normalizePriority(priority);
        for (Task t : tasks) {
            if (t.getPriority().equalsIgnoreCase(wanted)) {
                out.add(t);
            }
        }
        return out;
    }

    /**
     * Returns the tasks that contain the given tag (case-insensitive). The
     * result is a new list; the store is not modified.
     */
    public List<Task> filterByTag(String tag) {
        List<Task> out = new ArrayList<Task>();
        for (Task t : tasks) {
            if (t.hasTag(tag)) {
                out.add(t);
            }
        }
        return out;
    }

    /**
     * Returns the tasks ordered by deadline ascending (earliest first). Tasks
     * with no deadline are placed after all dated tasks; ties keep insertion
     * order. The result is a new list; the store is not modified.
     */
    public List<Task> sortByDeadline() {
        List<Task> out = new ArrayList<Task>(tasks);
        out.sort(new Comparator<Task>() {
            @Override
            public int compare(Task a, Task b) {
                String da = a.getDeadline();
                String db = b.getDeadline();
                boolean ea = da == null || da.trim().isEmpty();
                boolean eb = db == null || db.trim().isEmpty();
                if (ea && eb) {
                    return Integer.compare(a.getId(), b.getId());
                }
                if (ea) {
                    return 1;
                }
                if (eb) {
                    return -1;
                }
                return da.compareTo(db);
            }
        });
        return out;
    }

    /** Finds a task by id, or null when the current user has no such task. */
    public Task findById(int id) {
        for (Task t : tasks) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    /** Marks a task completed; returns the task, or null if the id is unknown. */
    public Task complete(int id) {
        Task task = findById(id);
        if (task == null) {
            return null;
        }
        task.setCompleted(true);
        save();
        return task;
    }

    /** Deletes a task; returns true when a task was actually removed. */
    public boolean delete(int id) {
        for (int i = 0; i < tasks.size(); i++) {
            if (tasks.get(i).getId() == id) {
                tasks.remove(i);
                save();
                return true;
            }
        }
        return false;
    }

    /** Rewrites the per-user task file with the current in-memory contents. */
    private void save() {
        try {
            Path parent = file.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            StringBuilder sb = new StringBuilder();
            for (Task t : tasks) {
                sb.append(t.getId()).append('|')
                  .append(t.getTitle()).append('|')
                  .append(t.getDescription()).append('|')
                  .append(t.getTimestamp()).append('|')
                  .append(t.statusText()).append('|')
                  .append(t.getPriority()).append('|')
                  .append(t.getDeadline()).append('|')
                  .append(t.tagsText()).append('\n');
            }
            Files.write(file, sb.toString().getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            System.out.println("Warning: could not save tasks: " + e.getMessage());
        }
    }
}

