import java.io.IOException;
import java.io.RandomAccessFile;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * SharedTaskStore - concurrency-safe, multi-user task repository backed by a
 * single shared database file (data/tasks.txt). This is the Subtask 5 storage
 * layer used when the program is launched as
 * {@code java -cp bin Main --user <username>}, so several processes (one per
 * terminal / user) can add, complete, delete, archive and refresh tasks
 * without corrupting the shared file.
 *
 * Concurrency strategy (two layers):
 *   1. An OS-level exclusive file lock ({@link FileChannel#lock()}) is held on
 *      data/tasks.txt for the whole read-modify-write cycle of every mutating
 *      operation, and for every read. This stops two separate JVM processes
 *      from interleaving their writes and producing a torn/partial file; the
 *      loser of the lock simply blocks until the winner finishes.
 *   2. Every public method is {@code synchronized} on this store instance, so
 *      multiple threads inside one process are also serialized.
 * Each acquisition prints a runtime log line to stdout containing "lock" /
 * "synchronized" (e.g. "[DEBUG] Acquiring lock on data/tasks.txt ...") so the
 * concurrency safety is directly observable in the captured output.
 *
 * Storage format: one task per line as
 *   owner|id|title|description|timestamp|status|priority|deadline|tags|archived
 * (ten '|'-separated fields). 'owner' is the username that created the task.
 * Blank lines and lines beginning with '#' are ignored. The format is a strict
 * superset of the Subtask 4 per-user format: if a line lacks the leading owner
 * field (10 fields expected, 9 present) it is treated as ownerless/legacy and
 * loaded with default attributes rather than crashing, so no data is lost.
 *
 * ID generation strategy: ids are unique across the whole shared file. Before
 * every write the file is re-read under the lock, the maximum existing id is
 * found and the new task gets max+1 (starting at 1). Because ids are recomputed
 * from disk each time, two concurrently running processes cannot hand out the
 * same id; ids are never reused after a delete.
 */
public class SharedTaskStore {

    /** Timestamp format used for the creation time recorded on each task. */
    private static final DateTimeFormatter TS_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    private final Path file;

    public SharedTaskStore() {
        this.file = Paths.get("data", "tasks.txt");
        ensureFile();
    }

    /** Creates the shared file (and data/ directory) if it does not exist yet. */
    private void ensureFile() {
        try {
            Path parent = file.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            if (!Files.exists(file)) {
                System.out.println("[DEBUG] synchronized create of shared store " + file);
                Files.createFile(file);
            }
        } catch (IOException e) {
            System.out.println("Warning: could not create shared task store: " + e.getMessage());
        }
    }

    /** Opens the file and blocks until an exclusive OS lock is acquired. */
    private RandomAccessFile openLocked() throws IOException {
        System.out.println("[DEBUG] Acquiring lock on " + file + " ...");
        RandomAccessFile raf = new RandomAccessFile(file.toFile(), "rw");
        FileChannel channel = raf.getChannel();
        FileLock lock = channel.lock();
        System.out.println("[DEBUG] Lock acquired (synchronized access to shared storage).");
        return new LockedFile(raf, lock);
    }

    /**
     * Small holder so the lock object can be released together with the file
     * handle. Returning it from openLocked keeps a single try/finally shape in
     * every calling method.
     */
    private static final class LockedFile extends RandomAccessFile {
        private final FileLock lock;

        LockedFile(RandomAccessFile raf, FileLock lock) throws IOException {
            super(raf.getFD());
            this.lock = lock;
        }

        void closeAll() {
            System.out.println("[DEBUG] Releasing lock (leaving synchronized section).");
            try {
                if (lock != null && lock.isValid()) {
                    lock.release();
                }
            } catch (IOException ignored) {
                // ignore - releasing best-effort
            }
            try {
                super.close();
            } catch (IOException ignored) {
                // ignore - closing best-effort
            }
        }
    }

    /** Reads the whole shared file into a string using the locked handle. */
    private String readContent(RandomAccessFile raf) throws IOException {
        long len = raf.length();
        byte[] data = new byte[(int) len];
        raf.seek(0);
        raf.readFully(data);
        return new String(data, StandardCharsets.UTF_8);
    }

    /** Parses the shared file content into Task objects (owner included). */
    private List<Task> parse(String content) {
        List<Task> out = new ArrayList<Task>();
        if (content == null) {
            return out;
        }
        String[] lines = content.split("\n");
        for (String raw : lines) {
            String line = raw.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }
            String[] parts = line.split("\\|", -1);
            // Expected: owner|id|title|description|timestamp|status|priority|
            //           deadline|tags|archived  (10 fields).
            // Tolerate a legacy 9-field per-user line (no owner prefix).
            String owner = "";
            int offset = 0;
            if (parts.length >= 10) {
                owner = parts[0];
                offset = 1;
            } else if (parts.length < 5) {
                continue;
            }
            try {
                int id = Integer.parseInt(parts[offset].trim());
                String title = parts[offset + 1];
                String description = parts[offset + 2];
                String timestamp = parts[offset + 3];
                boolean completed = parts[offset + 4].trim().equalsIgnoreCase("Completed");
                String priority = parts.length > offset + 5 ? parts[offset + 5] : Task.DEFAULT_PRIORITY;
                String deadline = parts.length > offset + 6 ? parts[offset + 6] : "";
                List<String> tags = parts.length > offset + 7 ? Task.parseTags(parts[offset + 7]) : new ArrayList<String>();
                boolean archived = parts.length > offset + 8 && parts[offset + 8].trim().equalsIgnoreCase("true");
                Task task = new Task(id, title, description, timestamp, completed, priority, deadline, tags, archived);
                task.setOwner(owner);
                out.add(task);
            } catch (NumberFormatException ignored) {
                // Skip malformed lines rather than aborting the read.
            }
        }
        return out;
    }

    /** Serializes tasks back into the shared-file format. */
    private String serialize(List<Task> tasks) {
        StringBuilder sb = new StringBuilder();
        for (Task t : tasks) {
            sb.append(t.getOwner()).append('|')
              .append(t.getId()).append('|')
              .append(t.getTitle()).append('|')
              .append(t.getDescription()).append('|')
              .append(t.getTimestamp()).append('|')
              .append(t.statusText()).append('|')
              .append(t.getPriority()).append('|')
              .append(t.getDeadline()).append('|')
              .append(t.tagsText()).append('|')
              .append(t.isArchived() ? "true" : "false").append('\n');
        }
        return sb.toString();
    }

    /** Overwrites the shared file with the given tasks using the locked handle. */
    private void writeContent(RandomAccessFile raf, List<Task> tasks) throws IOException {
        byte[] bytes = serialize(tasks).getBytes(StandardCharsets.UTF_8);
        raf.setLength(0);
        raf.seek(0);
        raf.write(bytes);
        raf.getFD().sync();
    }

    /** Reads every task in the shared database (any owner), under the lock. */
    public synchronized List<Task> readAll() {
        System.out.println("[DEBUG] synchronized read of shared store " + file);
        LockedFile lf = null;
        try {
            lf = (LockedFile) openLocked();
            return parse(readContent(lf));
        } catch (IOException e) {
            System.out.println("Warning: could not read shared task store: " + e.getMessage());
            return new ArrayList<Task>();
        } finally {
            if (lf != null) {
                lf.closeAll();
            }
        }
    }

    /** Returns only the tasks owned by the given user. */
    public List<Task> listFor(String owner) {
        List<Task> out = new ArrayList<Task>();
        for (Task t : readAll()) {
            if (t.getOwner().equalsIgnoreCase(owner)) {
                out.add(t);
            }
        }
        return out;
    }

    /**
     * Appends a new task for the given owner. The id is computed from the
     * current on-disk state while the exclusive lock is held, so concurrent
     * processes cannot collide.
     */
    public synchronized Task add(String owner, String title, String description,
                                 String priority, String deadline, List<String> tags) {
        System.out.println("[DEBUG] synchronized add to shared store " + file);
        LockedFile lf = null;
        try {
            lf = (LockedFile) openLocked();
            List<Task> all = parse(readContent(lf));
            int nextId = 1;
            for (Task t : all) {
                if (t.getId() >= nextId) {
                    nextId = t.getId() + 1;
                }
            }
            String now = LocalDateTime.now().format(TS_FORMAT);
            Task task = new Task(nextId, Task.sanitize(title), Task.sanitize(description), now, false,
                    priority, Task.sanitize(deadline), tags);
            task.setOwner(owner);
            all.add(task);
            writeContent(lf, all);
            return task;
        } catch (IOException e) {
            System.out.println("Warning: could not add task: " + e.getMessage());
            return null;
        } finally {
            if (lf != null) {
                lf.closeAll();
            }
        }
    }

    /** Marks the task with the given id completed, regardless of owner. */
    public synchronized Task complete(int id) {
        return mutate(id, new Mutator() {
            @Override
            public void apply(Task t) {
                t.setCompleted(true);
            }
        });
    }

    /** Archives the task with the given id (hidden from the default view). */
    public synchronized Task archive(int id) {
        return mutate(id, new Mutator() {
            @Override
            public void apply(Task t) {
                t.setArchived(true);
            }
        });
    }

    /** Unarchives the task with the given id (restored to the default view). */
    public synchronized Task unarchive(int id) {
        return mutate(id, new Mutator() {
            @Override
            public void apply(Task t) {
                t.setArchived(false);
            }
        });
    }

    /** Deletes the task with the given id; true when something was removed. */
    public synchronized boolean delete(int id) {
        System.out.println("[DEBUG] synchronized delete in shared store " + file);
        LockedFile lf = null;
        try {
            lf = (LockedFile) openLocked();
            List<Task> all = parse(readContent(lf));
            boolean removed = false;
            for (int i = 0; i < all.size(); i++) {
                if (all.get(i).getId() == id) {
                    all.remove(i);
                    removed = true;
                    break;
                }
            }
            if (removed) {
                writeContent(lf, all);
            }
            return removed;
        } catch (IOException e) {
            System.out.println("Warning: could not delete task: " + e.getMessage());
            return false;
        } finally {
            if (lf != null) {
                lf.closeAll();
            }
        }
    }

    /** Finds a task by id (read-only). */
    public Task findById(int id) {
        for (Task t : readAll()) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    /** Reloads the shared file and returns the current task count. */
    public int refresh() {
        return readAll().size();
    }

    /** Functional hook describing a single-field change to a task. */
    private interface Mutator {
        void apply(Task task);
    }

    /** Applies a mutation to the task with the given id, under the lock. */
    private Task mutate(int id, Mutator mutator) {
        LockedFile lf = null;
        try {
            lf = (LockedFile) openLocked();
            List<Task> all = parse(readContent(lf));
            Task found = null;
            for (Task t : all) {
                if (t.getId() == id) {
                    found = t;
                    break;
                }
            }
            if (found == null) {
                return null;
            }
            mutator.apply(found);
            writeContent(lf, all);
            return found;
        } catch (IOException e) {
            System.out.println("Warning: could not update task: " + e.getMessage());
            return null;
        } finally {
            if (lf != null) {
                lf.closeAll();
            }
        }
    }
}

