 * null when no user was supplied, in which case normal login is used.
 */
private static String parseUserArg(String[] args) {
    if (args == null) {
        return null;
    }
    for (int i = 0; i < args.length; i++) {
        if (args[i].equals("--user") && i + 1 < args.length) {
            return args[i + 1].trim();
