import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Shared multi-user main menu (Subtask 5). All storage operations go
 * through SharedTaskStore, which holds an exclusive file lock and prints
 * "[DEBUG] ... lock ..." / "synchronized" logs on every access. "List All"
 * shows tasks from every user so concurrently added work is visible, while
 * "List Mine" is scoped to the current username. "/refresh" reloads the
 * file and reports the latest data.
 */
private void sharedMenu(String username, SharedTaskStore shared) {
    while (true) {
        System.out.println();
        System.out.println("===== Shared Main Menu ===== [" + username + "]");
        System.out.println("1) Add Task          2) List All Tasks    3) List My Tasks");
        System.out.println("4) Mark Completed    5) Delete Task       6) Search Tasks");
        System.out.println("7) Archive Task      8) Unarchive Task    9) Refresh");
        System.out.println("10) Logout           11) Exit");
        System.out.println("Commands: /add /list /mine /complete <id> /delete <id> /search <text>");
        System.out.println("          /filter priority=high  /filter tag=<tag>  /sort deadline");
        System.out.println("          /archive <id>  /unarchive <id>  /refresh  /exit");
        String choice = readLine("Choose an option: ");
        if (choice == null) {
            goodbye();
            System.exit(0);
        }
        choice = choice.trim();
        if (choice.startsWith("/")) {
            handleSharedCommand(username, shared, choice);
            continue;
        }
        if (choice.equals("1") || choice.equalsIgnoreCase("add")) {
            sharedAddTask(username, shared);
        } else if (choice.equals("2")) {
            System.out.println();
            System.out.println("--- All Tasks (shared) ---");
            printTasks(shared.readAll());
        } else if (choice.equals("3")) {
            System.out.println();
            System.out.println("--- My Tasks ---");
            printTasks(shared.listFor(username));
        } else if (choice.equals("4")) {
            sharedCompleteTask(shared);
        } else if (choice.equals("5")) {
            sharedDeleteTask(shared);
        } else if (choice.equals("6")) {
            System.out.println();
            System.out.println("--- Search Tasks ---");
            String query = readLine("Search text: ");
            if (query == null) {
                return;
            }
            System.out.println("--- Search results for \"" + query.trim() + "\" ---");
            printTasks(searchList(shared.readAll(), query));
        } else if (choice.equals("7")) {
            sharedArchive(shared);
        } else if (choice.equals("8")) {
            sharedUnarchive(shared);
        } else if (choice.equals("9") || choice.equalsIgnoreCase("refresh")) {
            performSharedRefresh(shared);
        } else if (choice.equals("10") || choice.equalsIgnoreCase("logout")) {
            System.out.println("Logged out.");
            return;
        } else if (choice.equals("11") || choice.equalsIgnoreCase("exit")) {
            goodbye();
            System.exit(0);
        } else {
            System.out.println("Invalid option, please try again.");
        }
    }
}

/** Adds a task under the supplied username in the shared store. */
private void sharedAddTask(String username, SharedTaskStore shared) {
    System.out.println();
    System.out.println("--- Add Task (shared) ---");
    String title = readLine("Title: ");
    if (title == null) {
        return;
    }
    String description = readLine("Description: ");
    if (description == null) {
        return;
    }
    String priority = readLine("Priority (High/Medium/Low) [Medium]: ");
    if (priority == null) {
        return;
    }
    String deadline = readLine("Deadline (yyyy-MM-dd, blank for none): ");
    if (deadline == null) {
        return;
    }
    String tags = readLine("Tags (comma-separated, blank for none): ");
    if (tags == null) {
        return;
    }
    if (title.trim().isEmpty()) {
        System.out.println("Title must not be empty.");
        return;
    }
    Task task = shared.add(username, title.trim(), description.trim(),
            Task.normalizePriority(priority), deadline.trim(), Task.parseTags(tags));
    if (task != null) {
        System.out.println("Task " + task.getId() + " added: " + task.getTitle());
    } else {
        System.out.println("Task could not be added.");
    }
}

private void sharedCompleteTask(SharedTaskStore shared) {
    System.out.println();
    System.out.println("--- Mark Task Completed (shared) ---");
    Integer id = readId("Task ID to complete: ");
    if (id == null) {
        return;
    }
    if (shared.complete(id) != null) {
        System.out.println("Task " + id + " marked Completed");
    } else {
        System.out.println("Task " + id + " not found.");
    }
}

private void sharedDeleteTask(SharedTaskStore shared) {
    System.out.println();
    System.out.println("--- Delete Task (shared) ---");
    Integer id = readId("Task ID to delete: ");
    if (id == null) {
        return;
    }
    if (shared.delete(id)) {
        System.out.println("Task " + id + " deleted");
    } else {
        System.out.println("Task " + id + " not found.");
    }
}

private void sharedArchive(SharedTaskStore shared) {
    System.out.println();
    System.out.println("--- Archive Task (shared) ---");
    Integer id = readId("Task ID to archive: ");
    if (id == null) {
        return;
    }
    if (shared.archive(id) != null) {
        System.out.println("Task " + id + " archived, hiding from main list");
    } else {
        System.out.println("Task " + id + " not found.");
    }
}

private void sharedUnarchive(SharedTaskStore shared) {
    System.out.println();
    System.out.println("--- Unarchive Task (shared) ---");
    Integer id = readId("Task ID to unarchive: ");
    if (id == null) {
