/** Case-insensitive partial search over the given task list. */
private List<Task> searchList(List<Task> source, String query) {
    List<Task> out = new ArrayList<Task>();
    for (Task t : source) {
        if (t.matches(query)) {
            out.add(t);
        }
    }
    return out;
}

/** Filters a task list by priority (case-insensitive). */
private List<Task> filterByPriority(List<Task> source, String priority) {
    String wanted = Task.normalizePriority(priority);
    List<Task> out = new ArrayList<Task>();
    for (Task t : source) {
        if (!t.isArchived() && t.getPriority().equalsIgnoreCase(wanted)) {
            out.add(t);
        }
    }
    return out;
}

/** Filters a task list by tag (case-insensitive). */
private List<Task> filterByTag(List<Task> source, String tag) {
    List<Task> out = new ArrayList<Task>();
    for (Task t : source) {
        if (!t.isArchived() && t.hasTag(tag)) {
            out.add(t);
        }
    }
    return out;
}

/** Sorts a task list by deadline ascending, undated tasks last. */
private List<Task> sortByDeadline(List<Task> source) {
    List<Task> out = new ArrayList<Task>();
    for (Task t : source) {
        if (!t.isArchived()) {
            out.add(t);
        }
    }
    out.sort(new java.util.Comparator<Task>() {
        @Override
        public int compare(Task a, Task b) {
            String da = a.getDeadline();
            String db = b.getDeadline();
            boolean ea = da == null || da.trim().isEmpty();
            boolean eb = db == null || db.trim().isEmpty();
            if (ea && eb) {
                return Integer.compare(a.getId(), b.getId());
            }
            if (ea) {
                return 1;
            }
            if (eb) {
                return -1;
            }
            return da.compareTo(db);
        }
    });
    return out;
}

